from mk import *
from lib import fbd
STRICT["on"] = True
A = 17.5  # drawing angle of the incline (degrees)

def fig():
    g = Fig(560, 200, "גוף שמסתו m מונח על מדרון בזווית אלפא, יש חיכוך בינו לבין המדרון. כוח אופקי F דוחף אותו לכיוון המדרון")
    g.poly([(100, 170), (480, 170), (480, 50)], fill="var(--d-fill)"); g.ground(60, 520, 170)
    g.angle(100, 170, 50, 0, 17.5, "α", lr=66)
    g.block(290, 108, 50, 30, "m", angle=17.5)
    g.arrow(200, 118, 262, 118, "F", lx=196, ly=122, anchor="end")
    return g

def forces(note):
    return fbd([("F", 0, 1.0), ("mg", -90, 1.0), ("N", 90 + A, 1.1), ("fₖ", 180 + A, 0.7)],
               "תרשים כוחות: על הגוף פועלים הכוח F האופקי, כוח הכובד mg כלפי מטה, הכוח הנורמלי N בניצב למדרון, וכוח החיכוך במורד המדרון. הכיוון החיובי במעלה המדרון",
               positive=A, tilt=A, surface="below", note=note)

E(id="bagrut-1987-q3", year=1987, label="1987 שאלה 3", topic="energy", sub="en-work", diff=4, fig=fig,
  stem=r"על מדרון ששיפועו בזווית $\alpha$ מונח גוף שמסתו $m$. מקדם החיכוך בין הגוף למדרון הוא $\mu$. על הגוף מפעילים כוח $F$ קבוע ואופקי (ראו תרשים).",
  parts=[
    P("א", r"מה הגודל המזערי $F_{\min}$ של הכוח, שבעזרתו אפשר לדחוף את הגוף במעלה המדרון? האם תמיד אפשר למצוא כוח $F$ כזה? נמקו.", OPEN, ["fbd", "signs", "principle", "algebra"], [
        X(r"הכוח המזערי הוא הכוח שמזיז את הגוף במעלה המדרון במהירות קבועה, כלומר בלי תאוצה. נבנה תרשים כוחות, נבחר כיוון חיובי, ונכתוב משוואת כוחות בשני כיוונים: לאורך המדרון ובניצב לו."),
        D(r"תרשים הכוחות על הגוף", lambda: forces("הגוף נע במעלה המדרון")),
        S(r"בוחרים כיוון חיובי", r"השאלה לא קובעת כיוון. בוחרים את כיוון התנועה, במעלה המדרון, כחיובי. בניצב למדרון בוחרים כחיובי את הכיוון שיוצא מהמדרון", r"(+)\ \nearrow"),
        S(r"מפרקים את הכוח $F$ לרכיבים", r"הכוח אופקי והמדרון נטוי, ולכן לכוח יש רכיב לאורך המדרון ורכיב שלוחץ אל המדרון", r"F_{\parallel} = F\cos\alpha,\quad F_{\perp} = F\sin\alpha"),
        S(r"מפרקים את כוח הכובד לרכיבים", r"הרכיב לאורך המדרון מושך במורד, והרכיב הניצב לוחץ אל המדרון", r"mg_{\parallel} = mg\sin\alpha,\quad mg_{\perp} = mg\cos\alpha"),
        S(r"משוואת כוחות בניצב למדרון", r"אין תנועה בניצב למדרון, ולכן התאוצה בכיוון הזה אפס. הנורמלי הוא הכוח היחיד שפועל בכיוון החיובי, והוא מאזן את שני הרכיבים שלוחצים אל המדרון", r"N - mg\cos\alpha - F\sin\alpha = m \cdot 0", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מבודדים את הנורמלי", r"מעבירים את שני הרכיבים לאגף השני", r"N = mg\cos\alpha + F\sin\alpha"),
        S(r"כוח החיכוך", r"הגוף נע, ולכן החיכוך קינטי. הוא פועל נגד כיוון התנועה, כלומר במורד המדרון", r"f_k = \mu N = \mu(mg\cos\alpha + F\sin\alpha)", eq=r"f_k = \mu_k N"),
        S(r"משוואת כוחות לאורך המדרון", r"סכום הכוחות בכיוון החיובי פחות סכום הכוחות נגדו. בכיוון החיובי פועל רק רכיב הכוח F. נגד הכיוון החיובי פועלים רכיב הכובד והחיכוך. מהירות קבועה, ולכן התאוצה אפס", r"F\cos\alpha - mg\sin\alpha - \mu(mg\cos\alpha + F\sin\alpha) = m \cdot 0", eq=r"\Sigma\vec F = m\vec a"),
        S(r"פותחים סוגריים", r"מכפילים את מקדם החיכוך בכל אחד מהאיברים שבסוגריים", r"F\cos\alpha - mg\sin\alpha - \mu mg\cos\alpha - \mu F\sin\alpha = 0"),
        S(r"מעבירים אגפים", r"משאירים באגף אחד רק את האיברים שיש בהם F", r"F\cos\alpha - \mu F\sin\alpha = mg\sin\alpha + \mu mg\cos\alpha"),
        S(r"מוציאים גורם משותף", r"באגף שמאל F משותף, ובאגף ימין mg משותף", r"F(\cos\alpha - \mu\sin\alpha) = mg(\sin\alpha + \mu\cos\alpha)"),
        S(r"מחלקים", r"מחלקים את שני האגפים בביטוי שבסוגריים באגף שמאל", r"F_{\min} = mg\,\frac{\sin\alpha + \mu\cos\alpha}{\cos\alpha - \mu\sin\alpha}"),
        S(r"האם תמיד קיים כוח כזה", r"הכוח חייב להיות חיובי. המונה תמיד חיובי, ולכן גם המכנה צריך להיות חיובי. אם המכנה אפס או שלילי, אין כוח אופקי שמזיז את הגוף: ככל שמגדילים את הכוח, הוא לוחץ את הגוף אל המדרון ומגדיל את החיכוך יותר ממה שהוא דוחף", r"\cos\alpha - \mu\sin\alpha > 0 \;\Rightarrow\; \mu < \frac{\cos\alpha}{\sin\alpha}"),
    ], r"$F_{\min} = mg\,\frac{\sin\alpha + \mu\cos\alpha}{\cos\alpha - \mu\sin\alpha}$. לא תמיד: רק כאשר $\mu < \frac{\cos\alpha}{\sin\alpha}$", key=r"mg(sinα+μcosα)/(cosα−μsinα)"),
    P("ב", r"מפעילים כעת כוח אופקי שגודלו פי שלושה מהכוח המזערי, $F = 3F_{\min}$. מה גודל התאוצה של הגוף במעלה המדרון?", OPEN, ["fbd", "signs", "principle", "algebra"], [
        X(r"הכוחות שפועלים על הגוף הם אותם כוחות כמו בסעיף א, ובאותם כיוונים. ההבדל: עכשיו הכוח F גדול יותר, ולכן לגוף יש תאוצה במעלה המדרון. כותבים את אותה משוואת כוחות לאורך המדרון, אבל הפעם עם תאוצה."),
        D(r"תרשים הכוחות על הגוף (אותם כוחות כמו בסעיף א, הכוח F גדול יותר)", lambda: fbd([("F", 0, 1.5), ("mg", -90, 1.0), ("N", 90 + A, 1.3), ("fₖ", 180 + A, 0.8)], "תרשים כוחות: כוח F אופקי גדול, כוח הכובד, הנורמלי והחיכוך במורד המדרון. הכיוון החיובי במעלה המדרון", positive=A, tilt=A, surface="below", note="הגוף מאיץ במעלה המדרון")),
        S(r"הכיוון החיובי", r"כמו בסעיף א: במעלה המדרון, כיוון התנועה", r"(+)\ \nearrow"),
        S(r"משוואת כוחות לאורך המדרון", r"בכיוון החיובי פועל רכיב הכוח F. נגד הכיוון החיובי פועלים רכיב הכובד והחיכוך. הנורמלי מסעיף א לא השתנה בצורתו", r"F\cos\alpha - mg\sin\alpha - \mu(mg\cos\alpha + F\sin\alpha) = ma", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מסדרים כמו בסעיף א", r"פותחים סוגריים ומוציאים גורם משותף: F מהאיברים שיש בהם F, ו-mg משאר האיברים", r"F(\cos\alpha - \mu\sin\alpha) - mg(\sin\alpha + \mu\cos\alpha) = ma"),
        S(r"מציבים את הכוח", r"נתון שהכוח פי שלושה מהכוח המזערי", r"3F_{\min}(\cos\alpha - \mu\sin\alpha) - mg(\sin\alpha + \mu\cos\alpha) = ma"),
        S(r"משתמשים בתוצאה של סעיף א", r"בסעיף א מצאנו שהכוח המזערי כפול הסוגריים שווה ל-mg כפול הסוגריים השניים. מציבים את זה באיבר הראשון", r"F_{\min}(\cos\alpha - \mu\sin\alpha) = mg(\sin\alpha + \mu\cos\alpha)"),
        S(r"מציבים ומפשטים", r"פי שלושה מהביטוי, פחות פעם אחת אותו ביטוי, נותן פעמיים את הביטוי", r"3mg(\sin\alpha + \mu\cos\alpha) - mg(\sin\alpha + \mu\cos\alpha) = 2mg(\sin\alpha + \mu\cos\alpha) = ma"),
        S(r"מחלקים את משוואת הכוחות במסה", r"המסה מופיעה בשני האגפים ולכן מצטמצמת: התאוצה לא תלויה במסה", r"a = 2g(\sin\alpha + \mu\cos\alpha)"),
    ], r"$a = 2g(\sin\alpha + \mu\cos\alpha)$", key=r"2g(sinα+μcosα)"),
    P("ג", r"בתנאי סעיף ב (כלומר כאשר $F = 3F_{\min}$), הגוף עובר לאורך המדרון מרחק $\ell$. מה העבודה שעשה הכוח $F$ בדרך זו?", OPEN, ["principle", "algebra"], [
        X(r"העבודה של כוח קבוע היא הכוח כפול התזוזה כפול הקוסינוס של הזווית ביניהם. הכוח אופקי והתזוזה לאורך המדרון, ולכן הזווית ביניהם היא זווית המדרון."),
        S(r"עבודה של כוח קבוע", r"הזווית בין הכוח האופקי לבין התזוזה לאורך המדרון היא זווית המדרון", r"W = F\,\ell\cos\alpha", eq=r"W = F\cos\theta\,\Delta s"),
        S(r"מציבים את הכוח", r"בתנאי סעיף ב הכוח פי שלושה מהכוח המזערי", r"W = 3F_{\min}\,\ell\cos\alpha"),
        S(r"מציבים את הכוח המזערי מסעיף א", r"התוצאה של סעיף א", r"W = 3mg\,\ell\cos\alpha\;\frac{\sin\alpha + \mu\cos\alpha}{\cos\alpha - \mu\sin\alpha}"),
    ], r"$W = 3mg\,\ell\cos\alpha\,\frac{\sin\alpha + \mu\cos\alpha}{\cos\alpha - \mu\sin\alpha}$", key=r"mgℓ·cosα·(sinα+μcosα)/(cosα−μsinα)"),
  ],
  concepts=["מישור משופע", "חיכוך קינטי", "כוח אופקי על מדרון", "עבודה של כוח קבוע"],
  summary=r"דחיפה אופקית במעלה מדרון עם חיכוך: הכוח המזערי, מתי הוא לא קיים, התאוצה כשהכוח משולש, והעבודה.",
  review='הנחה שלי (לפי החלטת הבעלים).\nבתנאי סעיף ב הכוח פי 3 מהכוח המזערי, ולכן בסעיף ג העבודה היא עם המקדם 3. בדף התשובות הביטוי בלי המקדם 3.\nהפתרון נכתב מחדש בפורמט החדש: תרשים כוחות, כיוון חיובי, כל שלב אלגברי, ומשוואות מדף הנוסחאות.\nמה לבדוק: את הפורמט החדש של הפתרון.')
